mapper.select:
select s.structure_id as structureId, s.`name` as name, s.type_id as typeId, it.name as typeName, s.system_id as systemId, un.name as systemName, s.`state` as state, s.fuel_expires as fuelExpires, s.corporation_id as corporationId from `structure` s left join inv_types it on s.type_id = it.type_id left join universe_name un on s.system_id = un.id and un.category = 'solar_system'
s.corporation_id = #{corporationId}
and s.`name` like concat('%', #{name}, '%')
and s.`state` = #{state}
and (s.fuel_expires < date_add(now() + interval 8 hour,interval 72-8 hour) or s.fuel_expires is null)
order by ${sortColumn}
asc desc
order by s.structure_id desc
